package main

import "fmt"

func minAndMax(nums []int) (int, int) {
	low, high := nums[0], nums[0]
	for _, x := range nums {
		if x < low {
			low = x
		}
		if x > high {
			high = x
		}
	}
	return low, high
}

func main() {
	var n int
	fmt.Scan(&n)
	nums := make([]int, n)
	for i := range nums {
		fmt.Scan(&nums[i])
	}
	low, high := minAndMax(nums)
	fmt.Println(low, high)
}

